package com.xuhang.mealops.inventory.application;
import java.math.*; import java.time.LocalDate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.xuhang.mealops.ingredient.application.IngredientRepository; import com.xuhang.mealops.inventory.domain.*; import com.xuhang.mealops.measurement.domain.*;
@Service public class InventoryConsumptionApplicationService { private final InventoryConsumptionCoordinator coordinator; private final IngredientRepository ingredients; public InventoryConsumptionApplicationService(InventoryConsumptionCoordinator c,IngredientRepository i){coordinator=c;ingredients=i;} @Transactional public ConsumptionResult consume(long ingredientId,BigDecimal amount,String code){Unit u=Unit.fromCode(code).orElseThrow(()->new InvalidInventoryBatchException("Unknown unit")); Quantity q=Quantity.of(amount,u).convertTo(u.baseUnit()); if(ingredients.findById(ingredientId).isEmpty()) throw new com.xuhang.mealops.ingredient.application.IngredientNotFoundException(ingredientId); var result=coordinator.consume(ingredientId,q); return new ConsumptionResult(result.transactionId(),ingredientId,q,result.allocations()); } public record ConsumptionResult(long transactionId,long ingredientId,Quantity quantity,java.util.List<InventoryConsumptionAllocation> allocations){} }
